  5	export type JobStatus = 'queued' | 'running' | 'completed' | 'failed';
  6	
  7	/** One row of the `jobs` table, as SQLite returns it. */
  8	export interface JobRow {
  9	  seq: number;
 10	  id: string;
 11	  status: JobStatus;
 12	  input: string;
 13	  steps: number;
 14	  fail_attempts: number;
 15	  attempts: number;
 16	  completed: number;
 17	  result_output: string | null;
 18	  error: string | null;
 19	  /** Epoch milliseconds before which a queued job must not be claimed (retry back-off). */
 20	  run_after: number;
 21	  created_at: string;
 22	  updated_at: string;
 23	}
 24	
 25	/**
 26	 * Opens the SQLite database shared by the server and worker processes and makes sure the schema exists.
 27	 * Both processes call this; `CREATE ... IF NOT EXISTS` is safe to run from either.
 28	 */
 29	export function openDatabase(path: string = process.env.DATABASE_PATH ?? 'data/jobs.db'): DatabaseSync {
 30	  if (path !== ':memory:') mkdirSync(dirname(path), { recursive: true });
 31	  const db = new DatabaseSync(path);
 32	  // busy_timeout first: switching to WAL takes a brief exclusive lock, and the server and worker
 33	  // open the same database at once, so the loser must wait rather than fail.
 34	  db.exec('PRAGMA busy_timeout = 5000; PRAGMA journal_mode = WAL;');
 35	  db.exec(`
 36	    CREATE TABLE IF NOT EXISTS jobs (
 37	      seq INTEGER PRIMARY KEY AUTOINCREMENT,
 38	      id TEXT NOT NULL UNIQUE,
 39	      status TEXT NOT NULL,
 40	      input TEXT NOT NULL,
 41	      steps INTEGER NOT NULL,
 42	      fail_attempts INTEGER NOT NULL,
 43	      attempts INTEGER NOT NULL DEFAULT 0,
 44	      completed INTEGER NOT NULL DEFAULT 0,
 45	      result_output TEXT,
 46	      error TEXT,
 47	      run_after INTEGER NOT NULL DEFAULT 0,
 48	      created_at TEXT NOT NULL,
 49	      updated_at TEXT NOT NULL
 50	    );
 51	    CREATE INDEX IF NOT EXISTS jobs_claim ON jobs (status, run_after, seq);
 52	    CREATE TABLE IF NOT EXISTS idempotency (
 53	      key TEXT PRIMARY KEY,
 54	      payload TEXT NOT NULL,
 55	      job_id TEXT NOT NULL REFERENCES jobs (id)
 56	    );
 57	    CREATE TABLE IF NOT EXISTS heartbeat (
 58	      name TEXT PRIMARY KEY,
 59	      ts INTEGER NOT NULL
 60	    );
 61	  `);
 62	  return db;
 63	}
