 65	/** Converts a row to the public job representation defined in TASK.md. */
 66	export function jobToJson(r: JobRow) {
 67	  return {
 68	    id: r.id,
 69	    status: r.status,
 70	    input: r.input,
 71	    steps: r.steps,
 72	    failAttempts: r.fail_attempts,
 73	    attempts: r.attempts,
 74	    progress: { completed: r.completed, total: r.steps },
 75	    result: r.status === 'completed' ? { output: r.result_output } : null,
 76	    error: r.status === 'failed' ? r.error : null,
 77	    createdAt: r.created_at,
 78	    updatedAt: r.updated_at,
 79	  };
 80	}
