 82	/** Typed wrapper for `StatementSync.get`, whose return type is a generic record. */
 83	export function one<T>(db: DatabaseSync, sql: string, ...params: (string | number | null)[]): T | undefined {
 84	  return db.prepare(sql).get(...params) as unknown as T | undefined;
 85	}
 86	
 87	/** Typed wrapper for `StatementSync.all`. */
 88	export function many<T>(db: DatabaseSync, sql: string, ...params: (string | number | null)[]): T[] {
 89	  return db.prepare(sql).all(...params) as unknown as T[];
 90	}
