  9	/** The worker counts as up if its heartbeat is at most this old. */
 10	const WORKER_FRESH_MS = 3_000;
 11	/** Bodies larger than this are rejected; the job payload is at most ~1 KB of input. */
 12	const MAX_BODY_BYTES = 64 * 1024;
 13	const ALLOWED_FIELDS = new Set(['input', 'steps', 'failAttempts']);
 14	const IDEMPOTENCY_KEY = /^[A-Za-z0-9_-]{1,128}$/;
 15	
 16	interface FieldError {
 17	  field: string;
 18	  message: string;
 19	}
 20	
 21	interface Payload {
 22	  input: string;
 23	  steps: number;
 24	  failAttempts: number;
 25	}
 26	
 27	function send(res: ServerResponse, status: number, body: unknown): void {
 28	  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
 29	  res.end(JSON.stringify(body));
 30	}
 31	
 32	function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[]): void {
 33	  send(res, status, { error: { code, message, ...(fields ? { fields } : {}) } });
 34	}
 35	
 36	const notFound = (res: ServerResponse) => sendError(res, 404, 'not_found', 'No such resource.');
 37	const methodNotAllowed = (res: ServerResponse) => sendError(res, 405, 'method_not_allowed', 'Method not allowed for this path.');
 38	
 39	function isPlainObject(v: unknown): v is Record<string, unknown> {
 40	  return typeof v === 'object' && v !== null && !Array.isArray(v);
 41	}
 42	
 43	/** Reads the whole body as text. Resolves null if it exceeds MAX_BODY_BYTES. */
 44	function readBody(req: IncomingMessage): Promise<string | null> {
 45	  return new Promise((resolve, reject) => {
 46	    const chunks: Buffer[] = [];
 47	    let size = 0;
 48	    let tooLarge = false;
 49	    req.on('data', (chunk: Buffer) => {
 50	      size += chunk.length;
 51	      if (size > MAX_BODY_BYTES) {
 52	        tooLarge = true;
 53	        return; // keep draining so the response can be written
 54	      }
 55	      chunks.push(chunk);
 56	    });
 57	    req.on('end', () => resolve(tooLarge ? null : Buffer.concat(chunks).toString('utf8')));
 58	    req.on('error', reject);
 59	  });
 60	}
 61	
 62	/** Validates a parsed body. Returns the payload with defaults applied, or the offending fields. */
 63	function validatePayload(body: unknown): { payload: Payload } | { fields: FieldError[] } {
 64	  if (!isPlainObject(body)) return { fields: [{ field: 'body', message: 'The body must be a JSON object.' }] };
 65	  const fields: FieldError[] = [];
 66	  for (const key of Object.keys(body)) {
 67	    if (!ALLOWED_FIELDS.has(key)) fields.push({ field: key, message: 'Unknown field.' });
 68	  }
 69	
 70	  const { input, steps = 5, failAttempts = 0 } = body;
 71	  if (typeof input !== 'string') {
 72	    fields.push({ field: 'input', message: 'input is required and must be a string.' });
 73	  } else if (input.length < 1 || input.length > 1000) {
 74	    fields.push({ field: 'input', message: 'input must be 1 to 1000 characters.' });
 75	  } else if (input.trim() === '') {
 76	    fields.push({ field: 'input', message: 'input must not be only whitespace.' });
 77	  }
 78	
 79	  const checkInt = (name: string, value: unknown, min: number, max: number) => {
 80	    if (typeof value !== 'number' || !Number.isInteger(value) || value < min || value > max) {
 81	      fields.push({ field: name, message: `${name} must be an integer from ${min} to ${max}.` });
 82	    }
 83	  };
 84	  checkInt('steps', steps, 1, 20);
 85	  checkInt('failAttempts', failAttempts, 0, 5);
 86	
 87	  if (fields.length > 0) return { fields };
 88	  return { payload: { input: input as string, steps: steps as number, failAttempts: failAttempts as number } };
 89	}
