 91	function getJobRow(id: string): JobRow | undefined {
 92	  return one<JobRow>(db, 'SELECT * FROM jobs WHERE id = ?', id);
 93	}
 94	
 95	type CreateResult = { kind: 'created' | 'replayed'; row: JobRow } | { kind: 'conflict' };
 96	
 97	/**
 98	 * Creates a job, or resolves an idempotent replay, in one immediate transaction so that two
 99	 * submissions with the same key cannot both insert.
100	 */
101	function createJob(payload: Payload, key: string | undefined): CreateResult {
102	  const canonical = JSON.stringify({ input: payload.input, steps: payload.steps, failAttempts: payload.failAttempts });
103	  db.exec('BEGIN IMMEDIATE');
104	  let result: CreateResult;
105	  try {
106	    if (key !== undefined) {
107	      const existing = one<{ payload: string; job_id: string }>(db, 'SELECT payload, job_id FROM idempotency WHERE key = ?', key);
108	      if (existing) {
109	        const row = getJobRow(existing.job_id);
110	        result = existing.payload === canonical && row ? { kind: 'replayed', row } : { kind: 'conflict' };
111	        db.exec('COMMIT');
112	        return result;
113	      }
114	    }
115	    const id = randomUUID();
116	    const now = new Date().toISOString();
117	    db.prepare(
118	      `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, completed, run_after, created_at, updated_at)
119	       VALUES (?, 'queued', ?, ?, ?, 0, 0, 0, ?, ?)`,
120	    ).run(id, payload.input, payload.steps, payload.failAttempts, now, now);
121	    if (key !== undefined) {
122	      db.prepare('INSERT INTO idempotency (key, payload, job_id) VALUES (?, ?, ?)').run(key, canonical, id);
123	    }
124	    db.exec('COMMIT');
125	    result = { kind: 'created', row: getJobRow(id)! };
126	    return result;
127	  } catch (e) {
128	    db.exec('ROLLBACK');
129	    throw e;
130	  }
131	}
132	
133	async function handleCreate(req: IncomingMessage, res: ServerResponse): Promise<void> {
134	  const fields: FieldError[] = [];
135	
136	  const rawKey = req.headers['idempotency-key'];
137	  let key: string | undefined;
138	  if (rawKey !== undefined) {
139	    if (typeof rawKey === 'string' && IDEMPOTENCY_KEY.test(rawKey)) key = rawKey;
140	    else fields.push({ field: 'Idempotency-Key', message: 'Idempotency-Key must match ^[A-Za-z0-9_-]{1,128}$.' });
141	  }
142	
143	  const mediaType = (req.headers['content-type'] ?? '').split(';')[0]!.trim().toLowerCase();
144	  const text = await readBody(req);
145	  if (mediaType !== 'application/json') {
146	    fields.push({ field: 'body', message: 'Content-Type must be application/json.' });
147	  } else if (text === null) {
148	    fields.push({ field: 'body', message: `The body must be at most ${MAX_BODY_BYTES} bytes.` });
149	  } else {
150	    let parsed: unknown;
151	    let parsedOk = true;
152	    try {
153	      parsed = JSON.parse(text);
154	    } catch {
155	      parsedOk = false;
156	    }
157	    if (!parsedOk) fields.push({ field: 'body', message: 'The body is not valid JSON.' });
158	    else {
159	      const v = validatePayload(parsed);
160	      if ('fields' in v) fields.push(...v.fields);
161	      else {
162	        if (fields.length > 0) return sendError(res, 400, 'invalid_request', 'Invalid request.', fields);
163	        const result = createJob(v.payload, key);
164	        if (result.kind === 'conflict') {
165	          return sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
166	        }
167	        return send(res, result.kind === 'created' ? 201 : 200, jobToJson(result.row));
168	      }
169	    }
170	  }
171	
172	  sendError(res, 400, 'invalid_request', 'Invalid request.', fields);
173	}
