175	function handleHealth(res: ServerResponse): void {
176	  const hb = one<{ ts: number }>(db, "SELECT ts FROM heartbeat WHERE name = 'worker'");
177	  const up = hb !== undefined && Date.now() - hb.ts <= WORKER_FRESH_MS;
178	  send(res, 200, { status: 'ok', worker: up ? 'up' : 'down' });
179	}
