181	async function route(req: IncomingMessage, res: ServerResponse): Promise<void> {
182	  const path = new URL(req.url ?? '/', 'http://localhost').pathname;
183	  const method = req.method ?? 'GET';
184	
185	  if (path === '/health') return method === 'GET' ? handleHealth(res) : methodNotAllowed(res);
186	  if (path === '/') {
187	    if (method !== 'GET') return methodNotAllowed(res);
188	    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
189	    res.end(uiHtml);
190	    return;
191	  }
192	  if (path === '/api/jobs') {
193	    if (method === 'POST') return handleCreate(req, res);
194	    if (method !== 'GET') return methodNotAllowed(res);
195	    const rows = many<JobRow>(db, 'SELECT * FROM jobs ORDER BY seq DESC');
196	    return send(res, 200, { jobs: rows.map(jobToJson) });
197	  }
198	  const match = /^\/api\/jobs\/([^/]+)$/.exec(path);
199	  if (match) {
200	    if (method !== 'GET') return methodNotAllowed(res);
201	    let id: string;
202	    try {
203	      id = decodeURIComponent(match[1]!);
204	    } catch {
205	      return notFound(res);
206	    }
207	    const row = getJobRow(id);
208	    return row ? send(res, 200, jobToJson(row)) : notFound(res);
209	  }
210	  notFound(res);
211	}
212	
213	const port = Number(process.env.PORT ?? 3000);
214	const server = createServer((req, res) => {
215	  route(req, res).catch((e: unknown) => {
216	    console.error('request failed:', e);
217	    if (!res.headersSent) sendError(res, 500, 'internal_error', 'Internal server error.');
218	  });
219	});
220	
221	server.listen(port, () => console.log(`server listening on ${port}`));
222	
223	function shutdown(): void {
224	  server.close(() => {
225	    db.close();
226	    process.exit(0);
227	  });
228	  server.closeAllConnections();
229	}
230	process.on('SIGTERM', shutdown);
231	process.on('SIGINT', shutdown);
  1	import { setTimeout as sleep } from 'node:timers/promises';
  2	import { one, openDatabase, type JobRow } from './db.ts';
  3	
  4	/** Time per step. */
  5	const STEP_MS = 100;
  6	/** Back-off before a failed attempt is retried (the brief allows 250 ms to 2 s). */
  7	const RETRY_DELAY_MS = 500;
  8	/** Total attempts allowed, including the first. */
  9	const MAX_ATTEMPTS = 3;
 10	/** How long an idle worker waits before looking for queued jobs again (pickup must be within 1 s). */
 11	const POLL_MS = 200;
 12	
 13	const db = openDatabase();
 14	let stopping = false;
 15	
 16	for (const signal of ['SIGINT', 'SIGTERM'] as const) {
 17	  process.on(signal, () => {
 18	    stopping = true;
 19	  });
 20	}
 21	
 22	function isoNow(): string {
 23	  return new Date().toISOString();
 24	}
 25	
 26	/** Records that this worker is alive. The server reports "up" while this is at most 3 s old. */
 27	function heartbeat(): void {
 28	  db.prepare(
 29	    "INSERT INTO heartbeat (name, ts) VALUES ('worker', ?) ON CONFLICT (name) DO UPDATE SET ts = excluded.ts",
 30	  ).run(Date.now());
 31	}
 32	
 33	/**
 34	 * Jobs left `running` by a worker that died are queued again. The interrupted attempt is handed
 35	 * back (attempts is decremented), so it is re-run under the same attempt number and the retry rules
 36	 * still apply exactly as if it had not been interrupted.
 37	 */
 38	function recoverInterrupted(): number {
 39	  const result = db
 40	    .prepare("UPDATE jobs SET status = 'queued', attempts = MAX(attempts - 1, 0), completed = 0, run_after = 0, updated_at = ? WHERE status = 'running'")
 41	    .run(isoNow());
 42	  return Number(result.changes);
 43	}
 44	
 45	/** Atomically takes the oldest eligible queued job and marks it running for a new attempt. */
 46	function claimNext(): JobRow | undefined {
 47	  db.exec('BEGIN IMMEDIATE');
 48	  try {
 49	    const row = one<JobRow>(
 50	      db,
 51	      "SELECT * FROM jobs WHERE status = 'queued' AND run_after <= ? ORDER BY seq LIMIT 1",
 52	      Date.now(),
 53	    );
 54	    if (!row) {
 55	      db.exec('COMMIT');
 56	      return undefined;
 57	    }
 58	    db.prepare("UPDATE jobs SET status = 'running', attempts = attempts + 1, completed = 0, updated_at = ? WHERE seq = ?").run(isoNow(), row.seq);
 59	    db.exec('COMMIT');
 60	    return { ...row, status: 'running', attempts: row.attempts + 1, completed: 0 };
 61	  } catch (e) {
 62	    db.exec('ROLLBACK');
 63	    throw e;
 64	  }
 65	}
 66	
 67	function setProgress(job: JobRow, completed: number): void {
 68	  db.prepare('UPDATE jobs SET completed = ?, updated_at = ? WHERE seq = ?').run(completed, isoNow(), job.seq);
 69	}
 70	
 71	function complete(job: JobRow): void {
 72	  db.prepare(
 73	    "UPDATE jobs SET status = 'completed', result_output = ?, error = NULL, completed = steps, updated_at = ? WHERE seq = ?",
 74	  ).run(job.input.toUpperCase(), isoNow(), job.seq);
 75	}
 76	
 77	/** After a failed attempt: queue another attempt after a delay, or give up after the last one. */
 78	function failAttempt(job: JobRow): void {
 79	  if (job.attempts >= MAX_ATTEMPTS) {
 80	    db.prepare(
 81	      "UPDATE jobs SET status = 'failed', error = 'transient failure', result_output = NULL, completed = 0, updated_at = ? WHERE seq = ?",
 82	    ).run(isoNow(), job.seq);
 83	  } else {
 84	    db.prepare(
 85	      "UPDATE jobs SET status = 'queued', completed = 0, run_after = ?, updated_at = ? WHERE seq = ?",
 86	    ).run(Date.now() + RETRY_DELAY_MS, isoNow(), job.seq);
 87	  }
 88	}
 89	
 90	/** Hands an in-progress attempt back to the queue during a graceful shutdown. */
 91	function release(job: JobRow): void {
 92	  db.prepare(
 93	    "UPDATE jobs SET status = 'queued', attempts = MAX(attempts - 1, 0), completed = 0, run_after = 0, updated_at = ? WHERE seq = ?",
 94	  ).run(isoNow(), job.seq);
 95	}
 96	
 97	/** Runs one attempt of a job. Returns when the attempt has completed, failed, or been released. */
 98	async function processAttempt(job: JobRow): Promise<void> {
 99	  // Attempt n fails at its first step, before any progress, when n <= failAttempts.
100	  const willFail = job.attempts <= job.fail_attempts;
101	  for (let step = 1; step <= job.steps; step++) {
102	    await sleep(STEP_MS);
103	    if (stopping) return release(job);
104	    if (step === 1 && willFail) return failAttempt(job);
105	    setProgress(job, step);
106	    heartbeat();
107	  }
108	  complete(job);
109	}
110	
111	async function main(): Promise<void> {
112	  const recovered = recoverInterrupted();
113	  if (recovered > 0) console.log(`requeued ${recovered} interrupted job(s)`);
114	  heartbeat();
115	  console.log('worker started');
116	
117	  while (!stopping) {
118	    heartbeat();
119	    const job = claimNext();
120	    if (!job) {
121	      await sleep(POLL_MS);
122	      continue;
123	    }
124	    await processAttempt(job);
125	  }
126	
127	  db.close();
128	  console.log('worker stopped');
129	  process.exit(0);
130	}
131	
132	main().catch((e: unknown) => {
133	  console.error('worker failed:', e);
134	  process.exit(1);
135	});
